const string NativeCatalog="""{"models":[{"slug":"native-live","display_name":"Live native","shell_type":"shell_command","visibility":"list","supported_in_api":true,"priority":0,"support_verbosity":false,"truncation_policy":{"mode":"tokens","limit":10000},"experimental_supported_tools":[],"supported_reasoning_levels":[],"future_native_capability":{"preserved":true}},{"slug":"native-unavailable","display_name":"Unavailable"}]}""";
if(args.Contains("--env-fixture")){await FakeRuntime();return;}
if(args.Contains("debug")&&args.Contains("--bundled")){Console.Write(NativeCatalog);return;}
var count=0;void Check(bool value,string name){if(!value)throw new Exception(name);Console.WriteLine("PASS "+name);count++;}
async Task Reject<T>(Func<Task> action,string name)where T:Exception{try{await action();}catch(T){Check(true,name);return;}throw new Exception("Accepted "+name);}
var root=Path.Combine(Path.GetTempPath(),"veo-provider-bridge-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
try{
var provider=new ExternalProvider("fixture",ProviderPreset.Custom,"Fixture","https://upstream.invalid/v1",ProviderWireApi.Chat,true,[new("fixture/vendor/model","vendor/model","Actual fixture model",true,32000,64000),new("fixture/disabled","disabled","Disabled",false)]);
var consent=ProviderConsent.Approve(provider,ProviderRequestPurpose.Inference);
var vault=new MemorySecrets();var handler=new Upstream();using var service=new ExternalProviderService(vault,"fixture-device",handler);await service.Authentication.SaveApiKeyAsync(provider,"fixture-upstream-secret");
await using(var empty=new LocalProviderForwarder(service)){Check(empty.Start([provider with{Enabled=false}],new Dictionary<string,ProviderConsent>()).Count==0&&empty.Port is null,"disabled providers never create a listening endpoint");}
await using(var invalid=new LocalProviderForwarder(service)){await Reject<UnauthorizedAccessException>(()=>Task.Run(()=>invalid.Start([provider],new Dictionary<string,ProviderConsent>())) ,"route requires exact explicit provider approval");}
await using var forwarder=new LocalProviderForwarder(service);var bases=forwarder.Start([provider],new Dictionary<string,ProviderConsent>{{provider.Id,consent}});var address=new Uri(bases[provider.Id],"responses");var capability=forwarder.EnvironmentOverrides.Single().Value;
using var http=new HttpClient(new SocketsHttpHandler{UseProxy=false}){Timeout=TimeSpan.FromSeconds(8)};
async Task<HttpResponseMessage> Send(string? secret,string body="{\"model\":\"fixture/vendor/model\",\"stream\":true,\"input\":[{\"role\":\"user\",\"content\":\"Fixture only\"}]}",string? path=null,Action<HttpRequestMessage>? change=null){var request=new HttpRequestMessage(HttpMethod.Post,path is null?address:new Uri(bases[provider.Id],path)){Content=new StringContent(body,Encoding.UTF8,"application/json")};if(secret is not null)request.Headers.Authorization=new("Bearer",secret);change?.Invoke(request);return await http.SendAsync(request);}
using(var result=await Send(null))Check(result.StatusCode==HttpStatusCode.Unauthorized,"unauthenticated loopback requests rejected before upstream");
using(var result=await Send(new string('0',64)))Check(result.StatusCode==HttpStatusCode.Unauthorized,"wrong capability rejected");
using(var result=await Send(capability,change:r=>r.Headers.Add("Origin","https://unrelated.invalid")))Check((int)result.StatusCode==400,"browser-origin cross-site requests rejected");
using(var result=await Send(capability,change:r=>r.Headers.Host="unrelated.invalid"))Check(result.StatusCode==HttpStatusCode.Forbidden,"DNS-rebinding Host refused");
using(var result=await Send(capability,"{\"model\":\"fixture/disabled\",\"stream\":true}"))Check(result.StatusCode==HttpStatusCode.Forbidden,"disabled model refused");
using(var result=await Send(capability,path:"responses?target=https://evil.invalid"))Check(result.StatusCode==HttpStatusCode.NotFound,"query path cannot redirect upstream destination");
using(var result=await Send(capability,"{broken"))Check(result.StatusCode==HttpStatusCode.BadRequest,"invalid client JSON rejected");
Check(handler.Calls==0,"all authorization and model failures caused zero upstream calls");
using(var result=await Send(capability)){var body=await result.Content.ReadAsStringAsync();Check(result.StatusCode==HttpStatusCode.OK&&body.Contains("response.output_text.delta")&&body.Contains("response.completed"),"real loopback HTTP streams adapted Chat as Codex Responses");Check(handler.Model=="vendor/model"&&handler.Authorization=="Bearer fixture-upstream-secret"&&handler.Target=="https://upstream.invalid/v1/chat/completions","upstream model path, endpoint and protected credential remain exact");Check(!body.Contains(capability)&&!body.Contains("fixture-upstream-secret"),"no loopback or provider credential emitted in response");}
var raw=await RawAsync(forwarder.Port!.Value,$"POST /p/fixture/responses HTTP/1.1\r\nHost: 127.0.0.1:{forwarder.Port}\r\nAuthorization: Bearer {capability}\r\nContent-Length: {LocalProviderForwarder.MaximumBodyBytes+1}\r\n\r\n");Check(raw.StartsWith("HTTP/1.1 413"),"oversized body rejected before allocation or upstream request");
raw=await RawAsync(forwarder.Port.Value,$"POST /p/fixture/responses HTTP/1.1\r\nHost: 127.0.0.1:{forwarder.Port}\r\nContent-Length: 1\r\nContent-Length: 1\r\n\r\nx");Check(raw.StartsWith("HTTP/1.1 400"),"duplicate Content-Length smuggling refused");
await using(var other=new LocalProviderForwarder(service)){var alternate=other.Start([provider],new Dictionary<string,ProviderConsent>{{provider.Id,consent}});using var request=new HttpRequestMessage(HttpMethod.Post,new Uri(alternate[provider.Id],"responses")){Content=new StringContent("{\"model\":\"fixture/vendor/model\",\"stream\":true}")};request.Headers.Authorization=new("Bearer",capability);using var result=await http.SendAsync(request);Check(result.StatusCode==HttpStatusCode.Unauthorized,"independent profile/runtime capability cannot authorize another forwarder");}
handler.Fail=true;using(var result=await Send(capability)){var body=await result.Content.ReadAsStringAsync();Check(result.StatusCode==HttpStatusCode.Unauthorized&&!body.Contains("fixture-upstream-secret"),"provider authentication failure returns explicit redacted failure without fallback");}handler.Fail=false;
await CheckCancellation(provider,consent,Check);
forwarder.DisableProvider(provider.Id);var calls=handler.Calls;using(var result=await Send(capability))Check(result.StatusCode==HttpStatusCode.NotFound&&handler.Calls==calls,"disabled provider immediately loses route and performs no request");
using var bundled=JsonDocument.Parse(NativeCatalog);var merged=ExternalProviderRuntimeBridge.MergeCatalog(bundled.RootElement,["native-live"],[provider]);var rows=merged["models"]!.AsArray();Check(rows.Count==2&&rows[0]!["future_native_capability"]!["preserved"]!.GetValue<bool>()&&!rows.Any(x=>x!["slug"]!.GetValue<string>()=="native-unavailable"),"merged catalog preserves verified native bytes and removes unavailable bundled entries");Check(rows[1]!["slug"]!.GetValue<string>()=="fixture/vendor/model"&&rows[1]!["supported_reasoning_levels"]!.AsArray().Count==0&&rows[1]!["context_window"]!.GetValue<long>()==32000,"external catalog retains exact identity/context and invents no native effort choices");
var executable=Path.Combine(AppContext.BaseDirectory,OperatingSystem.IsWindows()?"Veo.ProviderBridge.Tests.exe":"Veo.ProviderBridge.Tests");
await using(var bridge=new ExternalProviderRuntimeBridge(service,root)){var overlay=await bridge.PrepareAsync(executable,[provider],["native-live"]);Check(overlay is not null&&overlay.Arguments.Any(x=>x.Contains("wire_api=\"responses\""))&&overlay.Arguments.Any(x=>x.Contains("supports_websockets=false"))&&overlay.EnvironmentOverrides.Keys.All(x=>x.StartsWith("VEO_LOOPBACK_TOKEN_")),"launch overlay uses local Responses and only ephemeral capability environment");var json=await File.ReadAllTextAsync(overlay!.CatalogPath);Check(!json.Contains("fixture-upstream-secret")&&!overlay.Arguments.Any(x=>x.Contains("fixture-upstream-secret")),"overlay catalog and CLI arguments contain no provider secret");Check(overlay.Models.Single().RuntimeProviderId=="veo-external-fixture"&&overlay.Models.Single().CatalogId=="fixture/vendor/model","exact model-to-config-provider mapping exposed to sole runtime owner");}
var envName="VEO_LOOPBACK_TOKEN_"+Guid.NewGuid().ToString("N").ToUpperInvariant();var envSecret=Convert.ToHexString(RandomNumberGenerator.GetBytes(32));
await using(var runtime=new CodexRuntimeService(new CodexRuntimeOptions{ExecutablePath=executable,AdditionalArguments=["--env-fixture"],EnvironmentOverrides=new Dictionary<string,string>{{envName,envSecret}}})){await runtime.StartAsync();var response=await runtime.RequestAsync("test/environment");Check(response.GetProperty("capabilityPresent").GetBoolean(),"selected child runtime receives ephemeral loopback capability");await Task.Delay(100);Check(!runtime.DiagnosticTail.Contains(envSecret),"naked capability split across stderr writes is redacted");}
await using(var runtime=new CodexRuntimeService(new CodexRuntimeOptions{ExecutablePath=executable,AdditionalArguments=["--env-fixture"],EnvironmentOverrides=new Dictionary<string,string>{{"OPENAI_API_KEY","provider-secret"}}})){await Reject<ArgumentException>(()=>runtime.StartAsync(),"provider credential environment injection refused");}
Check(!DiagnosticRedactor.Redact(envName+"="+envSecret).Contains(envSecret),"named loopback capability diagnostics redacted");
Console.WriteLine($"{count} provider bridge checks passed.");
}finally{if(Path.GetDirectoryName(Path.GetFullPath(root))==Path.GetTempPath().TrimEnd(Path.DirectorySeparatorChar)&&Path.GetFileName(root).StartsWith("veo-provider-bridge-"))Directory.Delete(root,true);}

static async Task<string> RawAsync(int port,string value){using var client=new TcpClient();await client.ConnectAsync(IPAddress.Loopback,port);await using var stream=client.GetStream();await stream.WriteAsync(Encoding.ASCII.GetBytes(value));using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(5));using var reader=new StreamReader(stream);return await reader.ReadToEndAsync(timeout.Token);}
static async Task CheckCancellation(ExternalProvider provider,ProviderConsent consent,Action<bool,string> check){var stopped=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);async IAsyncEnumerable<JsonObject> Pending(ExternalProvider _,JsonElement body,ProviderConsent approval,[EnumeratorCancellation]CancellationToken token){try{yield return new(){["type"]="response.created",["response"]=new JsonObject{["id"]="fixture"}};await Task.Delay(Timeout.Infinite,token);}finally{stopped.TrySetResult();}}await using var forwarder=new LocalProviderForwarder(Pending);var endpoint=forwarder.Start([provider],new Dictionary<string,ProviderConsent>{{provider.Id,consent}})[provider.Id];using var http=new HttpClient(new SocketsHttpHandler{UseProxy=false});using var request=new HttpRequestMessage(HttpMethod.Post,new Uri(endpoint,"responses")){Content=new StringContent("{\"model\":\"fixture/vendor/model\",\"stream\":true}")};request.Headers.Authorization=new("Bearer",forwarder.EnvironmentOverrides.Single().Value);using(var response=await http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead)){forwarder.DisableProvider(provider.Id);await stopped.Task.WaitAsync(TimeSpan.FromSeconds(4));check(true,"disabling provider cancels its in-flight upstream stream");}}
static async Task FakeRuntime(){var capability=Environment.GetEnvironmentVariables().Cast<System.Collections.DictionaryEntry>().FirstOrDefault(x=>x.Key.ToString()!.StartsWith("VEO_LOOPBACK_TOKEN_"));var secret=capability.Value?.ToString()??"";if(secret.Length>0){Console.Error.Write(secret[..20]);Console.Error.Flush();await Task.Delay(10);Console.Error.Write(secret[20..]);Console.Error.Flush();}while(await Console.In.ReadLineAsync() is {} line){using var message=JsonDocument.Parse(line);var root=message.RootElement;if(!root.TryGetProperty("id",out var id))continue;var method=root.GetProperty("method").GetString();object result=method=="test/environment"?new{capabilityPresent=secret.Length==64}:new{userAgent="fixture"};Console.WriteLine(JsonSerializer.Serialize(new{id=id.Clone(),result}));}}
sealed class MemorySecrets:IProviderSecretStore{readonly ConcurrentDictionary<string,string> data=new();public ValueTask<string?> ReadAsync(string key,CancellationToken token=default)=>ValueTask.FromResult(data.TryGetValue(key,out var value)?value:null);public ValueTask SaveAsync(string key,string secret,CancellationToken token=default){data[key]=secret;return ValueTask.CompletedTask;}public ValueTask DeleteAsync(string key,CancellationToken token=default){data.TryRemove(key,out _);return ValueTask.CompletedTask;}}
sealed class Upstream:HttpMessageHandler{public int Calls;public bool Fail;public string? Model,Authorization,Target;protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){Interlocked.Increment(ref Calls);Target=request.RequestUri!.AbsoluteUri;Authorization=request.Headers.Authorization?.ToString();using var doc=JsonDocument.Parse(await request.Content!.ReadAsStringAsync(token));Model=doc.RootElement.GetProperty("model").GetString();if(Fail)return new(HttpStatusCode.Unauthorized){Content=new StringContent("{\"error\":{\"message\":\"do not leak fixture-upstream-secret\"}}")};var sse="data: {\"id\":\"chat-fixture\",\"choices\":[{\"index\":0,\"delta\":{\"content\":\"Fixture response\"}}]}\n\ndata: {\"id\":\"chat-fixture\",\"choices\":[{\"index\":0,\"delta\":{},\"finish_reason\":\"stop\"}]}\n\ndata: [DONE]\n\n";return new(HttpStatusCode.OK){Content=new StringContent(sse,Encoding.UTF8,"text/event-stream")};}}
